@Composable fun TavernCreationScreen(vm:TavernCreationViewModel=hiltViewModel(),onCreated:()->Unit){val s by vm.ui.collectAsState();LaunchedEffect(s.created){if(s.created)onCreated()};Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(24.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){Text("Fundar sua taberna");TavernPreview(s.name,s.emblem);TavernNameField(s.name,vm::name);androidx.compose.material3.OutlinedTextField(s.description,vm::description,label={Text("Descrição (opcional)")},modifier=Modifier.fillMaxWidth(),minLines=2);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){androidx.compose.material3.Switch(checked=s.isPrivate,onCheckedChange=vm::setPrivate);Text("Taberna privada")};TavernEmblemSelector(s.emblem,vm::emblem);s.error?.let{Text(it,color=androidx.compose.material3.MaterialTheme.colorScheme.error)};GoldButton(if(s.saving)"Criando…" else "Fundar Taberna",vm::save,enabled=s.name.isNotBlank()&&!s.saving)}}
